/**
 * Starter catalogue (P3-B3, P3-L2). Names are catalogue keys. The documents are bundled into the code
 * (bundled-documents.ts, generated by `starters:build`), so the packaged app, which has no package directory to
 * read, has them too. Each is checked like an imported file before it is shown or forked; a bad one is omitted
 * so the rest still list, and the starters tests fail the build when a shipped file is bad.
 */
import {
  err,
  ok,
  ValidationError,
  type AppLocale,
  type AsyncResult,
  type HubTemplateV0,
  type Result,
  type StarterSummary,
} from '@taalcut/core';
import { inspectTemplateDocument, inspectTemplateFile, type FileRead } from '../library/template-file';
import { BUNDLED_STARTERS } from './bundled-documents';
import { STARTER_MANIFEST } from './manifest';
import type { StarterEntry } from './manifest-schema';

function documentOf(inspected: FileRead): Result<HubTemplateV0> {
  if (inspected.ok) return ok(inspected.doc);
  return err(ValidationError({ field: 'file' }, { detail: JSON.stringify(inspected.problems.slice(0, 50)) }));
}

/** A starter file's text, checked as `template.import` checks a file. */
export function readStarterDocument(text: string): Result<HubTemplateV0> {
  return documentOf(inspectTemplateFile(text));
}

/** One manifest entry's bundled document. A file that isn't bundled (or leaves the directory) is refused. */
export async function loadStarter(entry: StarterEntry): Promise<Result<HubTemplateV0>> {
  const raw = BUNDLED_STARTERS.get(entry.file);
  if (raw === undefined) return err(ValidationError({ field: 'file' }, { detail: entry.file }));
  return documentOf(inspectTemplateDocument(raw));
}

/** Says which bundled file was left out and why (a corrupt install). */
export type StarterLog = (line: string) => void;

/**
 * At most 10 summaries for `locale` (the six global starters plus that locale's own), in catalogue order.
 * `forLibrary` ("best fit for the library first") would rank by the person's clips, which this package can't
 * see; until a library port gives it those counts, both orders are the catalogue's (SPEC, P3-B3).
 */
export async function starterSummaries(
  input: { readonly locale: AppLocale; readonly forLibrary: boolean },
  entries: readonly StarterEntry[],
  read: (entry: StarterEntry) => Promise<Result<HubTemplateV0>>,
  log: StarterLog = console.error,
): Promise<StarterSummary[]> {
  const chosen = entries
    .filter((entry) => entry.locales === 'all' || entry.locales.includes(input.locale))
    .sort((a, b) => a.order - b.order);
  const summaries: StarterSummary[] = [];
  for (const entry of chosen) {
    if (summaries.length >= 10) break;
    const loaded = await read(entry);
    if (!loaded.ok) {
      log(`[templates] starter ${entry.id} omitted: ${loaded.error.code}`);
      continue;
    }
    summaries.push({
      starterId: entry.id,
      nameKey: entry.nameKey,
      formatId: entry.formatId,
      needs: entry.needs,
      structure: loaded.value.structure,
    });
  }
  return summaries;
}

export function createStarterCatalogue(deps: { readonly log?: StarterLog } = {}) {
  return {
    starters(input: {
      readonly locale: AppLocale;
      readonly forLibrary: boolean;
    }): AsyncResult<StarterSummary[]> {
      return starterSummaries(input, STARTER_MANIFEST, loadStarter, deps.log).then((items) => ok(items));
    },
  };
}
